DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'cash_account_type') THEN CREATE TYPE public.cash_account_type AS ENUM ('business', 'personal'); END IF; END $$;

CREATE TABLE IF NOT EXISTS public.cash_reconciliations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_type public.cash_account_type NOT NULL, account_name text,
  reconciled_balance numeric NOT NULL DEFAULT 0, reconciliation_date date NOT NULL DEFAULT CURRENT_DATE, note text,
  created_at timestamptz NOT NULL DEFAULT now(), created_by uuid DEFAULT auth.uid()
);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.cash_reconciliations TO authenticated;
GRANT ALL ON public.cash_reconciliations TO service_role;
ALTER TABLE public.cash_reconciliations ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Admins manage cash reconciliations" ON public.cash_reconciliations;
CREATE POLICY "Admins manage cash reconciliations" ON public.cash_reconciliations FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE INDEX IF NOT EXISTS idx_cash_reconciliations_type_date ON public.cash_reconciliations(account_type, reconciliation_date DESC, created_at DESC);

ALTER TABLE public.debt_payments ADD COLUMN IF NOT EXISTS paid_from text, ADD COLUMN IF NOT EXISTS affects_live_cash boolean NOT NULL DEFAULT true;
ALTER TABLE public.bills ADD COLUMN IF NOT EXISTS paid_from text, ADD COLUMN IF NOT EXISTS payment_method text, ADD COLUMN IF NOT EXISTS affects_live_cash boolean NOT NULL DEFAULT true;
ALTER TABLE public.bill_occurrences ADD COLUMN IF NOT EXISTS affects_live_cash boolean NOT NULL DEFAULT true;
CREATE UNIQUE INDEX IF NOT EXISTS bill_occurrences_bill_month_uniq ON public.bill_occurrences (bill_id, period_month);

CREATE OR REPLACE FUNCTION public.recompute_debt_balance(_debt_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$
DECLARE v_paid numeric := 0; v_start numeric := 0; v_current numeric := 0;
BEGIN IF _debt_id IS NULL THEN RETURN; END IF; SELECT COALESCE(SUM(amount),0) INTO v_paid FROM public.debt_payments WHERE debt_id = _debt_id; SELECT COALESCE(starting_balance,0) INTO v_start FROM public.debts WHERE id = _debt_id; v_current := GREATEST(v_start - v_paid, 0); UPDATE public.debts SET current_balance = v_current, paid_off = (v_current <= 0), updated_at = now() WHERE id = _debt_id; END $function$;

CREATE OR REPLACE FUNCTION public.recompute_all_debt_balances() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$
DECLARE r record; n int := 0; BEGIN IF NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'admin only'; END IF; FOR r IN SELECT id FROM public.debts LOOP PERFORM public.recompute_debt_balance(r.id); n := n + 1; END LOOP; RETURN n; END $function$;
GRANT EXECUTE ON FUNCTION public.recompute_all_debt_balances() TO authenticated;

CREATE OR REPLACE FUNCTION public.reverse_allocation_batch(_allocation_id uuid, _note text DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$
DECLARE updated_count int := 0; BEGIN IF NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'admin only'; END IF; UPDATE public.allocations SET status = 'reversed', notes = concat_ws(E'\n', notes, COALESCE(_note, 'Reversed by admin')), updated_at = now() WHERE id = _allocation_id; GET DIAGNOSTICS updated_count = ROW_COUNT; UPDATE public.owner_pay_transfers SET status = 'reversed', notes = concat_ws(E'\n', notes, 'Reversed with allocation'), updated_at = now() WHERE allocation_id = _allocation_id AND status NOT IN ('reversed','cancelled'); RETURN updated_count > 0; END $function$;
GRANT EXECUTE ON FUNCTION public.reverse_allocation_batch(uuid, text) TO authenticated;

CREATE OR REPLACE FUNCTION public.fix_bill_occurrences(_today date DEFAULT CURRENT_DATE) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$
DECLARE b record; m date; month_start date := date_trunc('month', _today)::date; created_count int := 0; fixed_count int := 0; existed_count int := 0; rows_changed int := 0; due_day int; due_for_month date; inserted_id uuid;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'admin only'; END IF;
  FOR b IN SELECT id, amount, due_date, paid, paid_on, bill_type FROM public.bills WHERE recurring = true AND COALESCE(recurring_frequency, 'monthly') = 'monthly' LOOP
    FOR m IN SELECT generate_series(month_start - interval '2 months', month_start + interval '1 month', interval '1 month')::date LOOP
      due_day := COALESCE(EXTRACT(day FROM b.due_date)::int, 1);
      due_for_month := (m + (LEAST(due_day, EXTRACT(day FROM (date_trunc('month', m) + interval '1 month - 1 day'))::int) - 1) * interval '1 day')::date;
      inserted_id := NULL;
      INSERT INTO public.bill_occurrences(bill_id, period_month, due_date, amount, paid, paid_on, paid_amount, paid_from, payment_method, affects_live_cash)
      VALUES (b.id, m, due_for_month, b.amount, CASE WHEN b.paid_on IS NOT NULL AND date_trunc('month', b.paid_on)::date = m THEN b.paid ELSE false END, CASE WHEN b.paid_on IS NOT NULL AND date_trunc('month', b.paid_on)::date = m THEN b.paid_on ELSE NULL END, CASE WHEN b.paid_on IS NOT NULL AND date_trunc('month', b.paid_on)::date = m AND b.paid THEN b.amount ELSE 0 END, CASE WHEN b.paid_on IS NOT NULL AND date_trunc('month', b.paid_on)::date = m AND b.paid THEN b.bill_type ELSE NULL END, NULL, true)
      ON CONFLICT (bill_id, period_month) DO NOTHING RETURNING id INTO inserted_id;
      IF inserted_id IS NULL THEN existed_count := existed_count + 1; ELSE created_count := created_count + 1; END IF;
    END LOOP;
    UPDATE public.bill_occurrences o SET paid = false, paid_on = NULL, paid_amount = 0, paid_from = NULL, payment_method = NULL, updated_at = now() WHERE o.bill_id = b.id AND o.period_month = month_start AND o.paid = true AND (o.paid_on IS NULL OR date_trunc('month', o.paid_on)::date <> month_start);
    GET DIAGNOSTICS rows_changed = ROW_COUNT; fixed_count := fixed_count + rows_changed;
  END LOOP;
  DELETE FROM public.bill_occurrences a USING public.bill_occurrences b WHERE a.bill_id = b.bill_id AND a.period_month = b.period_month AND a.id > b.id;
  GET DIAGNOSTICS rows_changed = ROW_COUNT; fixed_count := fixed_count + rows_changed;
  RETURN jsonb_build_object('created', created_count, 'fixed', fixed_count, 'already_existed', existed_count);
END $function$;
GRANT EXECUTE ON FUNCTION public.fix_bill_occurrences(date) TO authenticated;

DROP VIEW IF EXISTS public.v_business_live_cash;
CREATE VIEW public.v_business_live_cash AS WITH latest AS (SELECT reconciled_balance, reconciliation_date FROM public.cash_reconciliations WHERE account_type = 'business' ORDER BY reconciliation_date DESC, created_at DESC LIMIT 1), base AS (SELECT COALESCE((SELECT reconciled_balance FROM latest), 0) AS balance, (SELECT reconciliation_date FROM latest) AS since_date, EXISTS (SELECT 1 FROM latest) AS reconciled), payments_in AS (SELECT COALESCE(SUM(amount),0) AS amt FROM public.job_payments, base WHERE base.reconciled AND paid_on >= base.since_date), voucher_cash_in AS (SELECT COALESCE(SUM(amount_paid),0) AS amt FROM public.service_vouchers, base WHERE base.reconciled AND purchase_date >= base.since_date AND status NOT IN ('void','cancelled','refunded')), historical_in AS (SELECT COALESCE(SUM(amount),0) AS amt FROM public.historical_income, base WHERE base.reconciled AND entry_date >= base.since_date AND count_in_cash = true AND already_spent = false AND (scope IS NULL OR scope='business')), materials_out AS (SELECT COALESCE(SUM(cost),0) AS amt FROM public.job_materials, base WHERE base.reconciled AND paid_by = 'me' AND COALESCE(purchased_on, created_at::date) >= base.since_date), worker_pay_out AS (SELECT COALESCE(SUM(amount),0) AS amt FROM public.worker_payments, base WHERE base.reconciled AND paid_on >= base.since_date), bills_out AS (SELECT COALESCE(SUM(o.paid_amount),0) AS amt FROM public.bill_occurrences o JOIN public.bills b ON b.id = o.bill_id, base WHERE base.reconciled AND o.paid = true AND COALESCE(o.affects_live_cash, true) = true AND o.paid_on >= base.since_date AND COALESCE(o.paid_from, b.bill_type) = 'business'), one_time_bills_out AS (SELECT COALESCE(SUM(amount),0) AS amt FROM public.bills, base WHERE base.reconciled AND recurring = false AND paid = true AND COALESCE(affects_live_cash, true) = true AND paid_on >= base.since_date AND COALESCE(paid_from, bill_type) = 'business'), debt_out AS (SELECT COALESCE(SUM(dp.amount),0) AS amt FROM public.debt_payments dp JOIN public.debts d ON d.id = dp.debt_id, base WHERE base.reconciled AND dp.paid_on >= base.since_date AND COALESCE(dp.affects_live_cash, true) = true AND COALESCE(dp.paid_from, d.debt_scope, 'business') = 'business'), transfers_out AS (SELECT COALESCE(SUM(amount),0) AS amt FROM public.owner_pay_transfers, base WHERE base.reconciled AND transferred_on >= base.since_date AND status NOT IN ('reversed','cancelled')) SELECT CASE WHEN (SELECT reconciled FROM base) THEN (SELECT balance FROM base) + (SELECT amt FROM payments_in) + (SELECT amt FROM voucher_cash_in) + (SELECT amt FROM historical_in) - (SELECT amt FROM materials_out) - (SELECT amt FROM worker_pay_out) - (SELECT amt FROM bills_out) - (SELECT amt FROM one_time_bills_out) - (SELECT amt FROM debt_out) - (SELECT amt FROM transfers_out) ELSE 0 END AS live_cash, (SELECT amt FROM payments_in) AS payments_in, (SELECT amt FROM voucher_cash_in) AS voucher_cash_in, (SELECT amt FROM historical_in) AS historical_in, (SELECT amt FROM materials_out) AS materials_out, (SELECT amt FROM worker_pay_out) AS worker_pay_out, ((SELECT amt FROM bills_out) + (SELECT amt FROM one_time_bills_out)) AS bills_out, (SELECT amt FROM debt_out) AS debt_out, (SELECT amt FROM transfers_out) AS transfers_out, (SELECT reconciled FROM base) AS is_reconciled, (SELECT since_date FROM base) AS reconciliation_date, (SELECT balance FROM base) AS reconciled_balance;
GRANT SELECT ON public.v_business_live_cash TO authenticated; ALTER VIEW public.v_business_live_cash SET (security_invoker = true);

DROP VIEW IF EXISTS public.v_personal_live_cash;
CREATE VIEW public.v_personal_live_cash AS WITH latest AS (SELECT reconciled_balance, reconciliation_date FROM public.cash_reconciliations WHERE account_type = 'personal' ORDER BY reconciliation_date DESC, created_at DESC LIMIT 1), base AS (SELECT COALESCE((SELECT reconciled_balance FROM latest), 0) AS balance, (SELECT reconciliation_date FROM latest) AS since_date, EXISTS (SELECT 1 FROM latest) AS reconciled), transfers_in AS (SELECT COALESCE(SUM(amount),0) AS amt FROM public.owner_pay_transfers, base WHERE base.reconciled AND transferred_on >= base.since_date AND status NOT IN ('reversed','cancelled')), owner_worker_pay_in AS (SELECT COALESCE(SUM(wte.amount),0) AS amt FROM public.worker_time_entries wte JOIN public.workers w ON w.id = wte.worker_id, base WHERE base.reconciled AND w.is_owner = true AND COALESCE(wte.paid_at::date, wte.work_date) >= base.since_date AND (wte.paid = true OR wte.status = 'paid')), personal_income_in AS (SELECT COALESCE(SUM(amount),0) AS amt FROM public.personal_expenses, base WHERE base.reconciled AND is_income = true AND expense_date >= base.since_date), historical_personal_in AS (SELECT COALESCE(SUM(amount),0) AS amt FROM public.historical_income, base WHERE base.reconciled AND entry_date >= base.since_date AND count_in_cash = true AND already_spent = false AND scope='personal'), personal_exp_out AS (SELECT COALESCE(SUM(amount),0) AS amt FROM public.personal_expenses, base WHERE base.reconciled AND is_income = false AND expense_date >= base.since_date), bills_out AS (SELECT COALESCE(SUM(o.paid_amount),0) AS amt FROM public.bill_occurrences o JOIN public.bills b ON b.id = o.bill_id, base WHERE base.reconciled AND o.paid = true AND COALESCE(o.affects_live_cash, true) = true AND o.paid_on >= base.since_date AND COALESCE(o.paid_from, b.bill_type) = 'personal'), one_time_bills_out AS (SELECT COALESCE(SUM(amount),0) AS amt FROM public.bills, base WHERE base.reconciled AND recurring = false AND paid = true AND COALESCE(affects_live_cash, true) = true AND paid_on >= base.since_date AND COALESCE(paid_from, bill_type) = 'personal'), debt_out AS (SELECT COALESCE(SUM(dp.amount),0) AS amt FROM public.debt_payments dp JOIN public.debts d ON d.id = dp.debt_id, base WHERE base.reconciled AND dp.paid_on >= base.since_date AND COALESCE(dp.affects_live_cash, true) = true AND COALESCE(dp.paid_from, d.debt_scope, 'personal') = 'personal') SELECT CASE WHEN (SELECT reconciled FROM base) THEN (SELECT balance FROM base) + (SELECT amt FROM transfers_in) + (SELECT amt FROM owner_worker_pay_in) + (SELECT amt FROM personal_income_in) + (SELECT amt FROM historical_personal_in) - (SELECT amt FROM personal_exp_out) - (SELECT amt FROM bills_out) - (SELECT amt FROM one_time_bills_out) - (SELECT amt FROM debt_out) ELSE 0 END AS live_cash, (SELECT amt FROM transfers_in) AS transfers_in, (SELECT amt FROM personal_income_in) AS personal_income_in, (SELECT amt FROM personal_exp_out) AS personal_exp_out, (SELECT amt FROM bills_out) + (SELECT amt FROM one_time_bills_out) AS bills_out, (SELECT amt FROM debt_out) AS debt_out, (SELECT reconciled FROM base) AS is_reconciled, (SELECT since_date FROM base) AS reconciliation_date, (SELECT balance FROM base) AS reconciled_balance, (SELECT amt FROM owner_worker_pay_in) AS owner_worker_pay_in;
GRANT SELECT ON public.v_personal_live_cash TO authenticated; ALTER VIEW public.v_personal_live_cash SET (security_invoker = true);

CREATE OR REPLACE VIEW public.v_business_assigned AS WITH latest AS (SELECT reconciliation_date FROM public.cash_reconciliations WHERE account_type = 'business' ORDER BY reconciliation_date DESC, created_at DESC LIMIT 1), alloc AS (SELECT COALESCE(SUM(COALESCE(owner_pay_amount,0) + COALESCE(overhead_amount,0) + COALESCE(reserve_amount,0)),0) AS amt FROM public.allocations WHERE COALESCE(status,'assigned') IN ('assigned','allocated') AND EXISTS (SELECT 1 FROM latest) AND period_week >= (SELECT reconciliation_date FROM latest)), buckets AS (SELECT COALESCE(SUM(amount),0) AS amt FROM public.business_assignments WHERE status = 'assigned' AND EXISTS (SELECT 1 FROM latest) AND assigned_on >= (SELECT reconciliation_date FROM latest)) SELECT (SELECT amt FROM alloc) + (SELECT amt FROM buckets) AS assigned_total;
GRANT SELECT ON public.v_business_assigned TO authenticated; ALTER VIEW public.v_business_assigned SET (security_invoker = true);

CREATE OR REPLACE VIEW public.v_personal_assigned AS WITH latest AS (SELECT reconciliation_date FROM public.cash_reconciliations WHERE account_type = 'personal' ORDER BY reconciliation_date DESC, created_at DESC LIMIT 1) SELECT COALESCE(SUM(amount),0) AS assigned_total FROM public.personal_assignments WHERE status = 'assigned' AND EXISTS (SELECT 1 FROM latest) AND created_at::date >= (SELECT reconciliation_date FROM latest);
GRANT SELECT ON public.v_personal_assigned TO authenticated; ALTER VIEW public.v_personal_assigned SET (security_invoker = true);

CREATE OR REPLACE VIEW public.v_open_job_balances AS SELECT COALESCE(SUM(balance_due),0) AS open_balance FROM public.jobs WHERE COALESCE(balance_due,0) > 0 AND COALESCE(payment_status::text, 'unpaid') <> 'paid' AND COALESCE(archived, false) = false;
GRANT SELECT ON public.v_open_job_balances TO authenticated; ALTER VIEW public.v_open_job_balances SET (security_invoker = true);

CREATE OR REPLACE VIEW public.v_bill_month_totals AS WITH current_month AS (SELECT date_trunc('month', CURRENT_DATE)::date AS m), rows AS (SELECT b.bill_type, o.amount, o.paid, o.paid_on, o.paid_from, o.payment_method, o.due_date, o.period_month FROM public.bill_occurrences o JOIN public.bills b ON b.id = o.bill_id, current_month cm WHERE o.period_month = cm.m OR (o.paid = false AND o.due_date < cm.m)) SELECT COALESCE(SUM(amount) FILTER (WHERE period_month = (SELECT m FROM current_month)),0) AS total_monthly_bills, COALESCE(SUM(amount) FILTER (WHERE paid = true AND paid_on >= (SELECT m FROM current_month) AND paid_on < ((SELECT m FROM current_month) + interval '1 month')),0) AS paid_this_month, COALESCE(SUM(amount) FILTER (WHERE paid = false AND period_month = (SELECT m FROM current_month)),0) AS remaining_this_month, COALESCE(SUM(amount) FILTER (WHERE paid = false AND due_date < (SELECT m FROM current_month)),0) AS past_due_unpaid, COALESCE(SUM(amount) FILTER (WHERE paid = false AND bill_type = 'business'),0) AS business_bills_remaining, COALESCE(SUM(amount) FILTER (WHERE paid = false AND bill_type = 'personal'),0) AS personal_bills_remaining FROM rows;
GRANT SELECT ON public.v_bill_month_totals TO authenticated; ALTER VIEW public.v_bill_month_totals SET (security_invoker = true);